/**
 * Static GridStack callbacks for Vue — same pattern as React gsCreateReactComponents.
 * Dispatches via DOM `_gridComp` / `_gridItemRef` back-refs (no closure over per-grid state).
 */
import { GridStack, Utils } from 'gridstack';
export function installGridStackVueCallbacks() {
    if (!GridStack.addRemoveCB) {
        GridStack.addRemoveCB = gsCreateVueComponents;
    }
    if (!GridStack.saveCB) {
        GridStack.saveCB = gsSaveAdditionalVueInfo;
    }
    if (!GridStack.updateCB) {
        GridStack.updateCB = gsUpdateVueComponents;
    }
}
/** @internal Walk up from `el` to find the nearest `_gridComp` back-ref. */
function nearestGridComp(el) {
    let node = el;
    while (node) {
        const comp = node._gridComp;
        if (comp)
            return comp;
        node = node.parentElement;
    }
    return undefined;
}
/** @internal */
export function gsCreateVueComponents(parent, w, add, isGrid) {
    if (add) {
        if (isGrid) {
            const classes = ['grid-stack'];
            if (w.class)
                classes.push(...w.class.split(' ').filter(Boolean));
            const el = Utils.createDiv(classes);
            // Inherit the host's _gridComp so nested-grid children can register teleport anchors.
            const inherited = nearestGridComp(parent);
            if (inherited)
                el._gridComp = inherited;
            parent.appendChild(el);
            return el;
        }
        const gridHost = parent._gridComp;
        if (!gridHost)
            return undefined;
        const itemClasses = ['grid-stack-item'];
        if (w.class)
            itemClasses.push(...w.class.split(' ').filter(Boolean));
        const el = Utils.createDiv(itemClasses);
        Utils.createDiv(['grid-stack-item-content'], el);
        const id = w.id;
        if (id) {
            el._gridItemRef = { id, gridComp: gridHost };
            if (w.component)
                gridHost.registerSyntheticItemId(id);
        }
        if (w.content) {
            const content = el.querySelector('.grid-stack-item-content');
            if (content)
                content.textContent = w.content;
        }
        return el;
    }
    const el = w.el;
    if (el?._gridItemRef) {
        const { id, gridComp } = el._gridItemRef;
        gridComp.unregisterSyntheticItemId(id);
        delete el._gridItemRef;
    }
    el?.remove();
    return undefined;
}
export function gsSaveAdditionalVueInfo(node, w) {
    const n = node;
    if (n.component != null)
        w.component = n.component;
    if (n.props != null)
        w.props = { ...n.props };
    // Strip runtime-only fields that must never appear in serialized output.
    delete w.visibleObservable;
    const el = node.el;
    const id = n.id;
    if (id && el?._gridItemRef?.gridComp?.mergeWidgetPropsForSave) {
        el._gridItemRef.gridComp.mergeWidgetPropsForSave(id, w);
    }
}
export function gsUpdateVueComponents(node) {
    const el = node.el;
    const ref = el?._gridItemRef;
    if (!ref)
        return;
    const { id, gridComp } = ref;
    const w = node;
    if (w.props)
        gridComp.deserializeWidget(id, w);
    gridComp.requestUpdate();
}
